asciistring_013B85 |[CUR:280]  Wise men tell a tale late [N][N][N]  at night of a great King [N][N][N]  destroyed by the temptation [N][N][N]  of evil- |

asciistring_013BE1 |[CUR:280]  The Freil Empire, as it was [N][N][N]  called in those days, [N][N][N]  was ruled by a powerful man, [N][N][N]  King Magridd- |

asciistring_013C3D |[CUR:240]  It seems most people thought [N][N][N]  the King was a fair and kind [N][N][N]  ruler- There were some, [N][N][N]  however, who felt the King [N][N][N]  himself was ruled by greed- |

asciistring_013CB6 |[CUR:240]  One day the King happened to [N][N][N]  overhear two guards talking [N][N][N]  about a man named Dr-Leo- [N][N][N]  Now Dr-Leo was considered [N][N][N]  by all to be a great inventor [N][N][N]  and a genius- |

asciistring_013D4D |[CUR:240][14:3]The King stayed up many [N][N][N][14:3]nights wondering how he [N][N][N][14:3]could use this great [N][N][N][14:3]inventor to make him even [N][N][N][14:3]more wealthy-|

asciistring_013DBA |[CUR:240]  All of the sudden the King [N][N][N]  had an idea- [N][N][N]  He ordered his guards to [N][N][N]  capture Dr-Leo and bring him [N][N][N]  to the castle at once!|

asciistring_013E2A |[CUR:300]  Soon Dr-Leo was brought to [N][N][N]  the castle- |

asciistring_013E51 |[CUR:240]  The King confined him in a [N][N][N]  small room and ordered him [N][N][N]  to invent a machine that [N][N][N]  would summon the King of [N][N][N]  evil, Deathtoll-|

asciistring_013EBF |[CUR:240]  Dr-Leo finally completed [N][N][N]  the machine- [N][N][N]  The King instantly called [N][N][N]  upon Deathtoll, hoping they [N][N][N]  might strike a deal-|

asciistring_013F35 |[CUR:240]  After many days the deal was [N][N][N]  complete- The King would [N][N][N]  bring Deathtoll all living [N][N][N]  creatures, and in return, [N][N][N]  Deathtoll would give him a [N][N][N]  gold piece for each-|

asciistring_013FCD |[CUR:280]  One by one, all living [N][N][N]  creatures began to disappear- [N][N][N]  Soon the world was completely [N][N][N]  empty- |

asciistring_014023 |[CUR:280][14:3]Two people were watching [N][N][N][14:3]this catastrophe, [N][N][N][14:3]the Master, and you, [N][N][N][14:3]his follower- |

asciistring_01406A |[CUR:240]  "The King was very foolish [N][N][N]  to be tempted by evil, [N][N][N]  however I will give him [N][N][N]  another chance- You must go [N][N][N]  down to Earth and revive the [N][N][N]  World!ˮ the Master said- |

asciistring_0140FA |[CUR:240]  On a ray of light you [N][N][N]  descended to Earth----- [N][N][N]  --A warrior sent to revive [N][N][N]  the living and punish evil- [N][N][N]  A SOUL BLAZER!!|

