asciistring_0141F1 |[CUR:2C0][14:3]All the creatures stopped [N][N][N][14:3]and looked at the beauty [N][N][N][14:3]of the sunset:|

asciistring_014228 |[CUR:240]  One was with his child¥ [N][N][N]  and one was with his friend¥ [N][N][N]  creatures were in awe of [N][N][N]  the scenery:|

asciistring_01426F |[CUR:2C0]  Suddenly¥ a light ray shot [N][N][N]  into the sky:[N][N][N]  However¥ no one noticed it:|

asciistring_0142BB |[CUR:2C0][14:3]Lisa was standing all by [N][N][N][14:3]herself:|

asciistring_0142E1 |[CUR:240][14:3]She used to feel lonely [N][N][N][14:3]when she saw the sunset¥ [N][N][N][14:3]but now¥ she thinks [N][N][N][14:3]it is beautiful:|

